const axisOrder = ["temperature", "humidity", "pressure"];

const ranges = {
  temperature: { label: "Temperature °C", min: -20, max: 35, unit: "°C" },
  humidity: { label: "Humidity %", min: 0, max: 100, unit: "%" },
  pressure: { label: "Pressure hPa", min: 980, max: 1040, unit: "hPa" },
};

const groupedRaw = {};

for (const s of context.panel.data.series) {
  const valueField = s.fields.find((f) => f.type === "number");
  if (!valueField) continue;

  const labels = valueField.labels || {};
  const stat = labels.stat;
  const field = labels.field;

  if (!stat || !field) continue;
  if (!axisOrder.includes(field)) continue;

  if (!groupedRaw[stat]) {
    groupedRaw[stat] = {};
  }

  const values = valueField.values;
  const idx = (values.length ?? 0) - 1;
  const value = values.get ? values.get(idx) : values[idx];

  if (value == null || Number.isNaN(Number(value))) continue;

  groupedRaw[stat][field] = Number(value);
}

function normalize(field, value) {
  const cfg = ranges[field];
  if (!cfg) return 0;

  const span = cfg.max - cfg.min;
  if (span <= 0) return 0;

  const pct = ((value - cfg.min) / span) * 100;
  return Math.max(0, Math.min(100, pct));
}

const seriesOrder = [
  { key: "day_min", name: "Day Min", symbol: "rect" },
  { key: "day_mean", name: "Day Mean", symbol: "circle" },
  { key: "day_max", name: "Day Max", symbol: "triangle" },
];

return {
  backgroundColor: "transparent",
  tooltip: {
    trigger: "item",
    formatter: function (params) {
      const raw = params.data.raw || {};
      return [
        `<b>${params.name}</b>`,
        `Temperature: ${raw.temperature?.toFixed(2) ?? "-"} °C`,
        `Humidity: ${raw.humidity?.toFixed(2) ?? "-"} %`,
        `Pressure: ${raw.pressure?.toFixed(2) ?? "-"} hPa`,
      ].join("<br/>");
    },
  },
  legend: {
    bottom: 10,
  },
  radar: {
    radius: "90%",
    splitNumber: 5,
    indicator: axisOrder.map((field) => ({
      name: ranges[field].label,
      min: 0,
      max: 100,
    })),
  },
  series: [
    {
      type: "radar",
      data: seriesOrder
        .filter(({ key }) => groupedRaw[key])
        .map(({ key, name, symbol }) => {
          const raw = groupedRaw[key];
          return {
            name,
            symbol,
            symbolSize: 8,
            raw,
            value: axisOrder.map((field) => normalize(field, raw[field] ?? NaN)),
            lineStyle: { width: 2 },
            areaStyle: { opacity: 0 },
          };
        }),
    },
  ],
};

