// =============================================================================
// Psychrometric Chart — ECharts getOption for Volkov Labs Business Charts
// Axes: Temperature (°C) x, Absolute Humidity (g/m³) y
// Overlays: iso-RH curves (20/40/60/80/100%), iso-enthalpy diagonals
// Live data: scatter colored by outdoor illuminance (lux)
//
// Required Prometheus queries (all range, not instant):
//   A — esp32_sensor_mean_60s{..., field="temperature", placement="outdoor", reference="true"}
//   B — weather:absolute_humidity:g_m3{placement="outdoor", reference="true"}
//   C — avg_over_time(esp32_sensor_mean_60s{..., sensor="bh1750", field="illuminance", placement="outdoor"}[5m])
// =============================================================================

// ---------------------------------------------------------------------------
// 1. Physics helpers
// ---------------------------------------------------------------------------

// DEBUG — paste at the very top, remove after fixing
console.log('series count:', context.panel.data.series.length);
context.panel.data.series.forEach((s, i) => {
  console.log(`series[${i}] name="${s.name}" refId="${s.refId}" fields:`,
    s.fields.map(f => `${f.name}(${f.type})`).join(', ')
  );
});

// Saturation vapor pressure (hPa) via Magnus formula
function satVaporPressure(T) {
  return 6.1078 * Math.exp((17.27 * T) / (T + 237.3));
}

// Absolute humidity at saturation (g/m³) for given T

function ahSat(T) {
  const es = satVaporPressure(T); // hPa
  return 216.7 * es / (T + 273.15); // g/m³
}

// Absolute humidity for given T and RH (%)
function ahAtRH(T, rh) {
  return ahSat(T) * (rh / 100);
}

// Enthalpy of moist air (kJ/kg dry air) from T (°C) and AH (g/m³)
// AH converted to specific humidity approximation: w ≈ AH/1200 kg/kg
function enthalpy(T, ah) {
  const pressure = 1013.25; // hPa, standard pressure for background overlay
  const vaporPressure = ah * (T + 273.15) / 216.7; // hPa
  const w = 0.62198 * vaporPressure / (pressure - vaporPressure);
  return 1.006 * T + w * (2501 + 1.86 * T);
}

function rhFromAh(T, ah) {
  return 100 * ah / ahSat(T);
}

// ---------------------------------------------------------------------------
// 2. Chart domain
// ---------------------------------------------------------------------------

const T_MIN = -5;
const T_MAX = 35;
const AH_MIN = 0;
const AH_MAX = 30;
const T_STEP = 0.5; // resolution for curve sampling

const temps = [];
for (let t = T_MIN; t <= T_MAX; t += T_STEP) temps.push(t);

// ---------------------------------------------------------------------------
// 3. Build iso-RH curves (background series)
// ---------------------------------------------------------------------------

const RH_LEVELS = [20, 40, 60, 80, 100];
const RH_COLORS = {
  20: 'rgba(100,160,255,0.25)',
  40: 'rgba(100,160,255,0.35)',
  60: 'rgba(100,200,255,0.45)',
  80: 'rgba( 80,220,200,0.50)',
  100: 'rgba( 60,240,140,0.60)',
};

const isoRHSeries = RH_LEVELS.map(rh => ({
  name: `RH ${rh}%`,
  type: 'line',
  xAxisIndex: 0,
  yAxisIndex: 0,
  showSymbol: false,
  silent: true,
  legendHoverLink: false,
  lineStyle: {
    color: RH_COLORS[rh],
    width: rh === 100 ? 2 : 1,
    type: rh === 100 ? 'solid' : 'dashed',
  },
  label: {
    show: true,
    position: 'end',
    formatter: `${rh}%`,
    color: RH_COLORS[rh].replace(/[\d.]+\)$/, '0.85)'),
    fontSize: 10,
  },
  data: temps
    .map(t => {
      const ah = ahAtRH(t, rh);
      return ah >= AH_MIN && ah <= AH_MAX ? [t, parseFloat(ah.toFixed(3))] : null;
    })
    .filter(Boolean),
  z: 1,
}));

// ---------------------------------------------------------------------------
// 4. Build iso-enthalpy diagonals
// ---------------------------------------------------------------------------

// Enthalpy levels to draw (kJ/kg). Typical outdoor range for Stockholm: 0–70
const H_LEVELS = [0, 10, 20, 30, 40, 50, 60, 70];

// For each enthalpy level h, find (T, AH) pairs where enthalpy(T, AH) = h
// Rearranging: h = 1.006T + (AH/1000)*(2501 + 1.86T)
// → AH = (h - 1.006T) / ((2501 + 1.86T) / 1000)
function ahForEnthalpy(T, h) {
  const denom = (2501 + 1.86 * T) / 1000;
  return (h - 1.006 * T) / denom;
}

const isoEnthalpySeries = H_LEVELS.map(h => ({
  name: `h=${h}`,
  type: 'line',
  xAxisIndex: 0,
  yAxisIndex: 0,
  showSymbol: false,
  silent: true,
  legendHoverLink: false,
  lineStyle: {
    color: 'rgba(255,200,80,0.20)',
    width: 1,
    type: 'dotted',
  },
  label: {
    show: true,
    position: 'insideStartTop',
    formatter: `${h} kJ`,
    color: 'rgba(255,200,80,0.45)',
    fontSize: 9,
  },
  data: temps
    .map(t => {
      const ah = ahForEnthalpy(t, h);
      return ah >= AH_MIN && ah <= AH_MAX ? [t, parseFloat(ah.toFixed(3))] : null;
    })
    .filter(Boolean),
  z: 1,
}));

// ---------------------------------------------------------------------------
// 5. Extract live data from Grafana series
// ---------------------------------------------------------------------------

// Find series by legendFormat label set in query editor
function getSeries(name) {
  return context.panel.data.series.find(s => s.name === name || s.refId === name);
}

function getValues(s) {
  if (!s) return [];
  const timeField = s.fields.find(f => f.type === 'time');
  const numField = s.fields.find(f => f.type === 'number');
  if (!timeField || !numField) return [];
  const times = timeField.values;
  const values = numField.values;
  const len = Math.min(times.length, values.length);
  const out = [];
  for (let i = 0; i < len; i++) out.push({ t: times[i], v: values[i] });
  return out;
}

const tempSeries = getSeries('temperature') || getSeries('A');
const ahSeries = getSeries('ah') || getSeries('B');
const luxSeries = getSeries('lux') || getSeries('C');

const tempPts = getValues(tempSeries);
const ahPts = getValues(ahSeries);
const luxPts = getValues(luxSeries);

// Align by nearest timestamp (within 90s tolerance)
const TOLERANCE_MS = 90_000;

function align(primary, secondary) {
  return primary.map(p => {
    const match = secondary.reduce((best, s) => {
      const d = Math.abs(s.t - p.t);
      return d < Math.abs((best?.t ?? Infinity) - p.t) ? s : best;
    }, null);
    return match && Math.abs(match.t - p.t) < TOLERANCE_MS
      ? { t: p.t, pv: p.v, sv: match.v }
      : null;
  }).filter(Boolean);
}

const aligned = align(tempPts, ahPts).map(pt => {
  const luxMatch = luxPts.reduce((best, l) => {
    const d = Math.abs(l.t - pt.t);
    return d < Math.abs((best?.t ?? Infinity) - pt.t) ? l : best;
  }, null);
  return {
    t: pt.t,
    temp: pt.pv,
    ah: pt.sv,
    lux: luxMatch && Math.abs(luxMatch.t - pt.t) < TOLERANCE_MS ? luxMatch.v : null,
  };
}).filter(p => p.temp != null && p.ah != null);

// ---------------------------------------------------------------------------
// 6. Map illuminance → color (log scale: 0.1 lux → 100000 lux)
// ---------------------------------------------------------------------------

function luxToColor(lux) {
  if (lux == null || lux <= 0) return 'rgba(80,80,180,0.7)';   // pre-dawn purple
  // log-normalize to [0,1]: 0.1 lux → 0, 100000 lux → 1
  const norm = Math.max(0, Math.min(1, Math.log10(lux + 0.1) / Math.log10(100000)));
  // interpolate: night blue → dawn orange → noon yellow-white
  if (norm < 0.5) {
    // blue → orange
    const t = norm / 0.5;
    const r = Math.round(80 + t * (255 - 80));
    const g = Math.round(80 + t * (160 - 80));
    const b = Math.round(180 + t * (20 - 180));
    return `rgba(${r},${g},${b},0.8)`;
  } else {
    // orange → bright yellow
    const t = (norm - 0.5) / 0.5;
    const r = Math.round(255);
    const g = Math.round(160 + t * (240 - 160));
    const b = Math.round(20 + t * (100 - 20));
    return `rgba(${r},${g},${b},0.85)`;
  }
}

// ---------------------------------------------------------------------------
// 7. Live scatter series
// ---------------------------------------------------------------------------

const scatterData = aligned.map(p => ({
  value: [p.temp, parseFloat(p.ah.toFixed(3))],
  itemStyle: { color: luxToColor(p.lux) },
  // tooltip payload
  _lux: p.lux,
  _t: p.temp,
  _ah: p.ah,
}));

const scatterSeries = {
  name: 'Outdoor air',
  type: 'scatter',
  xAxisIndex: 0,
  yAxisIndex: 0,
  symbolSize: 5,
  data: scatterData,
  z: 10,
  tooltip: { show: true },
};

// ---------------------------------------------------------------------------
// 9. Colorbar legend (manual — ECharts visualMap doesn't work well with
//    per-point itemStyle, so we draw a simple gradient annotation)
// ---------------------------------------------------------------------------

const colorbarGraphic = {
  type: 'group',
  right: 10,
  top: 40,
  children: [
    {
      type: 'rect',
      shape: { x: 0, y: 0, width: 12, height: 120 },
      style: {
        fill: {
          type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
          colorStops: [
            { offset: 0, color: 'rgba(255,240,100,0.9)' },
            { offset: 0.5, color: 'rgba(255,160,20,0.9)' },
            { offset: 1, color: 'rgba(80,80,180,0.9)' },
          ],
        },
      },
    },
    { type: 'text', style: { text: 'high lux', x: 16, y: 0, fill: 'rgba(200,200,200,0.7)', fontSize: 9 } },
    { type: 'text', style: { text: 'low lux', x: 16, y: 112, fill: 'rgba(200,200,200,0.7)', fontSize: 9 } },
  ],
};

// ---------------------------------------------------------------------------
// 10. Assemble and return
// ---------------------------------------------------------------------------

return {
  backgroundColor: 'transparent',

  graphic: colorbarGraphic,

  tooltip: {
    trigger: 'item',
    formatter: function (params) {
      if (params.seriesName !== 'Outdoor air') return params.seriesName;
      const d = params.data;
      const lux = d._lux != null ? d._lux.toFixed(0) + ' lux' : '—';
      const rh = rhFromAh(d._t, d._ah);
      return [
        '<b>Outdoor air state</b>',
        `T: ${d._t?.toFixed(2)} °C`,
        `AH: ${d._ah?.toFixed(2)} g/m³`,
        `RH ≈ ${rh.toFixed(0)} %`,
        `Illuminance: ${lux}`,
        `Enthalpy ≈ ${enthalpy(d._t, d._ah).toFixed(1)} kJ/kg`,
      ].join('<br/>');

    },
  },

  legend: {
    show: true,
    bottom: 0,
    textStyle: { color: 'rgba(180,180,180,0.8)', fontSize: 10 },
    data: [ 'Outdoor air'],
  },

  grid: {
    left: '8%', right: '6%', top: '6%', bottom: '12%',
    containLabel: true,
  },

  xAxis: {
    type: 'value',
    name: 'Temperature (°C)',
    nameLocation: 'middle',
    nameGap: 28,
    min: T_MIN,
    max: T_MAX,
    axisLine: { lineStyle: { color: 'rgba(180,180,180,0.4)' } },
    splitLine: { lineStyle: { color: 'rgba(180,180,180,0.1)' } },
    axisLabel: { color: 'rgba(180,180,180,0.7)', formatter: v => `${v}°` },
  },

  yAxis: {
    type: 'value',
    name: 'Absolute Humidity (g/m³)',
    nameLocation: 'middle',
    nameGap: 50,
    min: AH_MIN,
    max: AH_MAX,
    axisLine: { lineStyle: { color: 'rgba(180,180,180,0.4)' } },
    splitLine: { lineStyle: { color: 'rgba(180,180,180,0.1)' } },
    axisLabel: { color: 'rgba(180,180,180,0.7)', formatter: v => `${v}` },
  },

  series: [
    ...isoRHSeries,
    ...isoEnthalpySeries,
    scatterSeries,
  ],
};
